def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    truck_patches = image_patch.find("truck")
    car_patches = image_patch.find("car")

    if not truck_patches or not car_patches:
        return image_patch

    truck_depths = [p.compute_depth() for p in truck_patches]
    car_depths = [p.compute_depth() for p in car_patches]

    truck_behind_car = []
    for i, truck_depth in enumerate(truck_depths):
        for j, car_depth in enumerate(car_depths):
            if truck_depth < car_depth:
                truck_behind_car.append((i, j))

    if not truck_behind_car:
        return image_patch

    best_match = None
    min_distance = float('inf')
    for truck_idx, car_idx in truck_behind_car:
        truck_patch = truck_patches[truck_idx]
        car_patch = car_patches[car_idx]
        dist = abs(truck_patch.horizontal_center - car_patch.horizontal_center)
        if dist < min_distance:
            min_distance = dist
            best_match = truck_patch

    return best_match

